// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.pbv;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PassByValueDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));
        ReferenceMechanics mech = new ReferenceMechanics();

        // 1) PRIMITIVE copy: caller's int is unchanged by the method.
        int count = 5;
        mech.incrementCopy(count);
        log.info(() -> "After incrementCopy, caller count still = " + count); // 5

        // 2) MUTATION through copied reference IS visible (same object).
        mech.applyFee(rajesh, new BigDecimal("500"));
        log.info(() -> "After applyFee, Rajesh balance = Rs." + rajesh.getBalance()); // 999500

        // 3) REASSIGNING the parameter does NOT affect caller's variable.
        mech.reassign(priya);
        log.info(() -> "After reassign, Priya balance = Rs." + priya.getBalance()); // 250000 unchanged

        // 4) SWAP cannot work → proves pass-by-value (copies swapped, not originals).
        mech.swap(rajesh, priya);
        log.info(() -> "After swap attempt: first still Rajesh? "
                + rajesh.getHolderName().equals("Rajesh")); // true
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in ReferenceMechanics.java ───
class ReferenceMechanics {
    // Primitive: 'n' is a COPY; changing it never affects the caller.
    void incrementCopy(int n) { n = n + 1; }

    // Reference copy: mutating the SHARED object IS visible to the caller.
    void applyFee(Account account, BigDecimal fee) { account.debit(fee); }

    // Reassignment: only OUR copy of the handle changes; caller's is untouched.
    void reassign(Account account) {
        account = new Account("NEW9999", "Ghost", new BigDecimal("0")); // local only
    }

    // Swap: we swap OUR copies of the handles, caller's variables unaffected.
    void swap(Account a, Account b) {
        Account tmp = a; a = b; b = tmp; // no effect outside this method
    }
}
